function first_at_or_above(versions, target) {
  let lo = 0;
  let hi = versions.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (versions[mid] < target) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

